3	/// What a derived document carries from its source (spec §11 CJ-51 (b), (e);
4	/// road map "creator-jobs" CJ5b): which cache paths the kept media own, the
5	/// clone-or-copy that lands them, the graphic modules the kept clips draw,
6	/// and the fonts and assets beside them. `ProjectDocument+Derived.swift` is
7	/// the door that calls it, in CJ-51 (c)'s order.
8	///
9	/// Carried per kept media id `m` (a media the DERIVED snapshot still lists):
10	/// `thumbs/m/`; `peaks/m.bin` and its marker; `loudness/m.bin` and its
11	/// marker; `speech/m.bin` and its marker; `sync/m.bin`, `sync/m.pcm` and
12	/// their marker; every `device-transcripts/m-*.json`; for every kind folder
13	/// under `analysis/`, `analysis/<kind>/m.json` and `analysis/<kind>/m/`;
14	/// `transcripts/m.json` and its marker only when the file records
15	/// `remote_deleted: true` (one still owed a DELETE stays in the source, N4);
16	/// and the reversed render of each media a kept clip plays backwards (N5).
17	/// Never media files, `ramp-audio/`, `isolated/`, `voiced/` or
18	/// `graphics/history/`.
19	enum DerivedCarry {
20	
21	    /// What one carry copied: regular files, their bytes, and the seconds the
22	    /// copy took on the main thread.
23	    struct Report: Equatable {
24	        let files: Int
25	        let bytes: Int64
26	        let seconds: Double
27	
28	        static let none = Report(files: 0, bytes: 0, seconds: 0)
29	    }
30	
31	    // MARK: - Caches
32	
33	    /// Relative paths under `cacheDir` (files or folders) that exist and that
34	    /// `snapshot`'s media carry, sorted. `mediaURLs` resolves a media to the
35	    /// file its reversed render's digest was taken over.
36	    static func cachePaths(
37	        of snapshot: ProjectSnapshot, mediaURLs: [UInt32: URL], in cacheDir: URL
38	    ) -> [String] {
39	        let files = FileManager.default
40	        var paths: [String] = []
41	        func keep(_ relative: String) {
42	            if files.fileExists(atPath: cacheDir.appendingPathComponent(relative).path) {
43	                paths.append(relative)
44	            }
45	        }
46	        let analysisKinds = folders(in: cacheDir.appendingPathComponent("analysis"))
47	        let deviceTranscripts = names(in: cacheDir.appendingPathComponent(
48	            DeviceTranscriptCache.kind))
49	        for media in snapshot.media {
50	            let m = media.id
51	            keep("thumbs/\(m)")
52	            for kind in ["peaks", "loudness", "speech"] {
53	                keep("\(kind)/\(m).bin")
54	                keep("\(kind)/\(m).complete.json")
55	            }
56	            for name in ["\(m).bin", "\(m).pcm", "\(m).complete.json"] { keep("sync/\(name)") }
57	            for name in deviceTranscripts where name.hasPrefix("\(m)-") && name.hasSuffix(".json") {
58	                keep("\(DeviceTranscriptCache.kind)/\(name)")
59	            }
60	            for kind in analysisKinds {
61	                keep("analysis/\(kind)/\(m).json")
62	                keep("analysis/\(kind)/\(m)")
63	            }
64	            if MediaTranscript.read(for: m, in: cacheDir)?.header.remoteDeleted == true {
65	                keep("\(MediaImporter.transcriptsKind)/\(m).json")
66	                keep("\(MediaImporter.transcriptsKind)/\(m).complete.json")
67	            }
68	        }
69	        for name in reversedRenders(of: snapshot, mediaURLs: mediaURLs, in: cacheDir) {
70	            keep("\(ReverseCache.directoryName)/\(name)")
71	        }
72	        return paths.sorted()
73	    }
74	
75	    /// The file name of each existing reversed render a kept clip — top level
76	    /// or nest — plays, its media not an image (`reverseState`'s walk).
77	    private static func reversedRenders(
78	        of snapshot: ProjectSnapshot, mediaURLs: [UInt32: URL], in cacheDir: URL
79	    ) -> Set<String> {
80	        var media: [UInt32: MediaSnapshot] = [:]
81	        for entry in snapshot.media where media[entry.id] == nil { media[entry.id] = entry }
82	        var names: Set<String> = []
83	        for clip in snapshot.clips + snapshot.nests.flatMap(\.clips) where clip.source.isReversed {
84	            guard let id = clip.source.mediaID, let entry = media[id], entry.kind != .image,
85	                let source = mediaURLs[id],
86	                let url = ReverseCache.existing(media: id, source: source, in: cacheDir)
87	            else { continue }
88	            names.insert(url.lastPathComponent)
89	        }
90	        return names
91	    }
92	
93	    /// Each regular file under `paths` cloned from `source` to `destination`
94	    /// (`copyfile` with `COPYFILE_CLONE`, which falls back to a copy where
95	    /// the volume cannot clone), folders created; throws on the first
96	    /// failure, naming the file. Main.
97	    static func copy(_ paths: [String], from source: URL, to destination: URL) throws -> Report {
98	        let began = Date()
99	        let files = FileManager.default
100	        var count = 0
101	        var bytes: Int64 = 0
102	        func clone(_ relative: String) throws {
103	            let from = source.appendingPathComponent(relative)
104	            let to = destination.appendingPathComponent(relative)
105	            try files.createDirectory(
106	                at: to.deletingLastPathComponent(), withIntermediateDirectories: true)
107	            guard copyfile(from.path, to.path, nil, copyfile_flags_t(COPYFILE_CLONE)) == 0 else {
108	                let why = String(cString: strerror(errno))
109	                throw ReelCoreError(message: "cache/\(relative) could not be carried: \(why)")
110	            }
111	            count += 1
112	            let size = (try? files.attributesOfItem(atPath: to.path)[.size] as? NSNumber)
113	            bytes += size?.int64Value ?? 0
114	        }
115	        for relative in paths {
116	            var isFolder: ObjCBool = false
117	            let from = source.appendingPathComponent(relative)
118	            guard files.fileExists(atPath: from.path, isDirectory: &isFolder) else { continue }
119	            guard isFolder.boolValue else {
120	                try clone(relative)
121	                continue
122	            }
123	            try files.createDirectory(
124	                at: destination.appendingPathComponent(relative), withIntermediateDirectories: true)
125	            for inner in try regularFiles(under: from) { try clone("\(relative)/\(inner)") }
126	        }
127	        return Report(files: count, bytes: bytes, seconds: Date().timeIntervalSince(began))
128	    }
129	
130	    /// Every regular file under `folder`, as paths relative to it, sorted.
131	    private static func regularFiles(under folder: URL) throws -> [String] {
132	        let files = FileManager.default
133	        var found: [String] = []
134	        for relative in try files.subpathsOfDirectory(atPath: folder.path) {
135	            var isFolder: ObjCBool = false
136	            let path = folder.appendingPathComponent(relative).path
137	            if files.fileExists(atPath: path, isDirectory: &isFolder), !isFolder.boolValue {
138	                found.append(relative)
139	            }
140	        }
141	        return found.sorted()
142	    }
143	
144	    /// The folder names directly inside `folder`, sorted; none when it is absent.
145	    private static func folders(in folder: URL) -> [String] {
146	        names(in: folder).filter { name in
147	            var isFolder: ObjCBool = false
148	            return FileManager.default.fileExists(
149	                atPath: folder.appendingPathComponent(name).path, isDirectory: &isFolder)
150	                && isFolder.boolValue
151	        }
152	    }
153	
154	    /// The entries directly inside `folder`, sorted; none when it is absent.
155	    private static func names(in folder: URL) -> [String] {
156	        ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []).sorted()
157	    }
158	
159	    // MARK: - Graphics
160	
161	    /// Every graphic clip's module name, top level and every nest
162	    /// (`reconcileGraphicNames`' set).
163	    static func drawnGraphicNames(_ snapshot: ProjectSnapshot) -> Set<String> {
164	        Set(
165	            (snapshot.clips + snapshot.nests.flatMap(\.clips))
166	                .compactMap { $0.graphic?.name }.filter(GraphicStore.isModuleName))
167	    }
168	
169	    /// `<name>.js` of each drawn name present in `folder` through
170	    /// `store.write(name:bytes:)`; every regular file of `fonts/` and
171	    /// `assets/` through `store.importFile(from:into:as:)`; then ONE
172	    /// `store.rescan()`. Never `history/`. Main.
173	    static func carryGraphics(names: Set<String>, from folder: URL, into store: GraphicStore) throws {
174	        let files = FileManager.default
175	        for name in names.sorted() {
176	            let module = folder.appendingPathComponent(name + ".js")
177	            guard files.fileExists(atPath: module.path) else { continue }
178	            try store.write(name: name, bytes: try Data(contentsOf: module))
179	        }
180	        for subfolder in [GraphicStore.fontsFolderName, GraphicStore.assetsFolderName] {
181	            let from = folder.appendingPathComponent(subfolder, isDirectory: true)
182	            for name in Self.names(in: from) {
183	                var isFolder: ObjCBool = false
184	                let file = from.appendingPathComponent(name)
185	                guard files.fileExists(atPath: file.path, isDirectory: &isFolder),
186	                    !isFolder.boolValue
187	                else { continue }
188	                _ = try store.importFile(from: file, into: subfolder, as: name)
189	            }
190	        }
191	        store.rescan()
192	    }
193	}
