540	    /// A fresh landmarks request over `faces`, revision 3, 76 points.
541	    static func makeLandmarks(_ faces: [VNFaceObservation]) -> VNDetectFaceLandmarksRequest {
542	        let request = VNDetectFaceLandmarksRequest()
543	        request.revision = VNDetectFaceLandmarksRequestRevision3
544	        request.constellation = .constellation76Points
