815	/// A Vision analysis kind's compute device (spec §11 CO-11, CJ-32; road map
816	/// "creator-jobs" CJ3's toll, a pure move out of `AnalysisMasks.swift`): the
817	/// three devices every supported Mac has, a request pinned to one on every
818	/// stage it supports, and the devices it reads back — the stamp's `device`,
819	/// which a job compares before each request it runs.
820	enum AnalysisVision {
821	
822	    enum Device: String { case cpu, gpu, neuralEngine = "neural_engine" }
823	
824	    /// Sets `device` on every stage the request supports and answers the
825	    /// devices it reads back (sorted, `+`-joined; `auto` for a stage left
826	    /// unset).
827	    static func pin(_ request: VNRequest, to device: Device) -> String {
828	        guard let stages = try? request.supportedComputeStageDevices else { return "unavailable" }
829	        var names = Set<String>()
830	        for (stage, devices) in stages {
831	            if let pick = devices.first(where: { name(of: $0) == device.rawValue }) {
832	                request.setComputeDevice(pick, for: stage)
833	            }
834	            names.insert(request.computeDevice(for: stage).map(name(of:)) ?? "auto")
835	        }
836	        return names.isEmpty ? "auto" : names.sorted().joined(separator: "+")
837	    }
838	
839	    static func name(of device: MLComputeDevice) -> String {
840	        switch device {
841	        case .cpu: return Device.cpu.rawValue
842	        case .gpu: return Device.gpu.rawValue
843	        case .neuralEngine: return Device.neuralEngine.rawValue
844	        @unknown default: return "unknown"
845	        }
846	    }
847	}
