1003	        var errorDescription: String? {
1004	            switch self {
1005	            case .nothingToSplit(let named):
1006	                return (named ? "None of clips is" : "No clip on an unlocked track is")
1007	                    + " a media clip showing a moving picture, so there are no shot changes "
1008	                    + "to find."
1009	            case .ceiling(let added, let room):
