1065	    /// The requests the targets still need, one per media in first-target
1066	    /// order: each target's window asked of the store, a media's misses
1067	    /// merged into one request. Empty when every window is a hit. Main
1068	    /// thread; throws `analysisRequest`'s errors.
1069	    static func wants(_ targets: [Target], in document: ProjectDocument) throws -> [Want] {
1070	        var order: [UInt32] = []
1071	        var groups: [UInt32: [Target]] = [:]
1072	        for target in targets {
1073	            if groups[target.media.id] == nil { order.append(target.media.id) }
1074	            groups[target.media.id, default: []].append(target)
1075	        }
1076	        var wants: [Want] = []
1077	        for id in order {
1078	            let group = groups[id] ?? []
1079	            guard let media = group.first?.media else { continue }
1080	            let spans = group.map(\.times.window)
1081	            var misses: [AnalysisRequest] = []
1082	            for window in spans {
1083	                if let request = try document.analysisRequest(
1084	                    kind: .shots, media: media, window: window)
1085	                {
1086	                    misses.append(request)
1087	                }
1088	            }
1089	            guard let first = misses.first else { continue }
1090	            let request = AnalysisRequest(
1091	                kind: first.kind, cacheDir: first.cacheDir, media: first.media, url: first.url,
1092	                stamp: first.stamp, input: first.input,
1093	                ranges: AnalysisStore.merged(misses.flatMap(\.ranges)))
1094	            wants.append(Want(media: media, request: request))
1095	        }
1096	        return wants
1097	    }
