1100	
1101	    /// The ops and what they cut, from the store. Main thread. Throws
1102	    /// `notCached` when a window misses again, `ceiling` when the splits
1103	    /// would pass the clip ceiling, and `analysisRequest`'s errors.
1104	    static func plan(_ targets: [Target], in document: ProjectDocument) throws -> Plan {
1105	        if let missing = try wants(targets, in: document).first {
1106	            throw Refusal.notCached(missing.media.id)
1107	        }
1108	        guard let cacheDir = document.cacheDirectory else {
1109	            throw ProjectDocument.AnalysisRequestError.noCache
1110	        }
1111	        let edited = document.editedProject.snapshot
1112	        let fps = edited.canvas.fps
1113	        let frame = fps.frameDuration
1114	        var records: [UInt32: [AnalysisShots.Record]] = [:]
1115	        var ops: [ReelOp] = []
1116	        var cuts: [(clip: UInt32, at: [Ticks])] = []
1117	        var added = 0
1118	        for target in targets {
1119	            let clip = target.clip
1120	            let grid = AnalysisGrid(media: target.media)
1121	            let held = records[target.media.id] ?? AnalysisShots.decode(
1122	                AnalysisStore.readPayload(
1123	                    .shots, media: target.media.id, file: AnalysisShots.payloadName,
1124	                    in: cacheDir) ?? Data(),
1125	                count: grid.count)
1126	            records[target.media.id] = held
1127	            guard let window = grid.indices(
1128	                from: target.times.window.lowerBound, to: target.times.window.upperBound)
1129	            else { continue }
1130	            var times = Set<Ticks>()
1131	            for k in AnalysisShots.cuts(held, in: window) {
1132	                let time = target.times.clipTime(ofSource: held[k].pts)
1133	                let t = ReelTime.snapToFrame(clip.start + time, fps: fps)
1134	                if t - clip.start <= frame || clip.end - t <= frame { continue }
1135	                times.insert(t)
1136	            }
1137	            guard !times.isEmpty else { continue }
1138	            let partner = clip.linked.flatMap { edited.clip($0) }.flatMap { other in
1139	                other.linked == clip.id && edited.track(other.track).map { !$0.locked } == true
1140	                    ? other : nil
1141	            }
1142	            for t in times {
1143	                added += 1
1144	                if let partner, partner.start < t, t < partner.end { added += 1 }
1145	            }
1146	            let sorted = times.sorted()
1147	            cuts.append((clip: clip.id, at: sorted))
1148	            ops += sorted.reversed().map { ReelOp.split(clips: [clip.id], at: $0) }
1149	        }
1150	        let room = Int(RC_MAX_CLIPS) - clipCount(document.project.snapshot)
1151	        guard added <= room else { throw Refusal.ceiling(added: added, room: max(0, room)) }
1152	        return Plan(ops: ops, cuts: cuts, added: added)
1153	    }
