1163	extension MediaImporter {
1164	    /// The lane a media cache pass's three synchronous audio decodes run on —
1165	    /// `writePeaks`, `writeSyncFeatures` and `writeSpeech`, each reached
1166	    /// through `MediaImporter.onCacheLane` (spec §11 #367). At most `width`
1167	    /// bodies run at once, in the order they were submitted, on the lane's
1168	    /// own concurrent `.utility` queue and never on the Swift cooperative
1169	    /// pool.
1170	    ///
1171	    /// Why it exists: twenty imports of long files that nobody waited for put
1172	    /// every cache pass's `AVAssetReader` to work at once, each on a
1173	    /// cooperative-pool thread blocked in `copyNextSampleBuffer`; with the
1174	    /// pool full, every reader in the process — the ramp-audio render's on
1175	    /// its own queue included — stopped reading at 0 % CPU (#367). The lane
1176	    /// has two guards, each enough alone and kept together: its decodes run
1177	    /// off the pool (no synchronous `AVAssetReader` read runs on it), and
1178	    /// only two run at once, which also bounds what cache passes take from
1179	    /// playback, export and the ramp renderer. A queued body waits in
1180	    /// `pending` and holds no thread.
1181	    ///
1182	    /// `submit` never blocks its caller. A body must not wait on the lane
1183	    /// itself (a body that submitted and waited would hold a slot while it
1184	    /// waited); the writers end in `CacheLedger.publish`, which does not.
1185	    /// Thumbnails are not on the lane (spec §11 #367).
1186	    final class CacheLane: @unchecked Sendable {
1187	        /// Two at a time: a concurrency bound on audio decodes, not a memory
1188	        /// limit (spec §11 #367).
1189	        static let width = 2
1190	        static let label = "com.kgalligan.framejob.cache-lane"
1191	        static let shared = CacheLane(width: width)
1192	
1193	        private let width: Int
1194	        private let queue: DispatchQueue
1195	        private let lock = NSLock()
1196	        /// Bodies submitted and not yet started, oldest first.
1197	        private var pending: [() -> Void] = []
1198	        /// Bodies started and not yet finished; never above `width`.
1199	        private var running = 0
1200	
1201	        init(width: Int) {
1202	            self.width = width
1203	            queue = DispatchQueue(label: Self.label, qos: .utility, attributes: .concurrent)
1204	        }
1205	
1206	        /// FIFO; never blocks the caller; runs `body` on the lane's own
1207	        /// concurrent `.utility` DispatchQueue (labelled `label`) once fewer
1208	        /// than `width` bodies run.
1209	        func submit(_ body: @escaping () -> Void) {
1210	            lock.lock()
1211	            pending.append(body)
1212	            let next = takeLocked()
1213	            lock.unlock()
1214	            if let next { start(next) }
1215	        }
1216	
1217	        /// The oldest pending body, with its slot taken, when a slot is free.
1218	        private func takeLocked() -> (() -> Void)? {
1219	            guard running < width, !pending.isEmpty else { return nil }
1220	            running += 1
1221	            return pending.removeFirst()
1222	        }
1223	
1224	        /// Runs `body` on the queue; when it returns, its slot goes to the
1225	        /// oldest pending body.
1226	        private func start(_ body: @escaping () -> Void) {
1227	            let run = { [self] in
1228	                body()
1229	                lock.lock()
1230	                running -= 1
1231	                let next = takeLocked()
1232	                lock.unlock()
1233	                if let next { start(next) }
1234	            }
1235	            queue.async(execute: run)
1236	        }
1237	    }
1238	}
