238	/// The `shots` kind (spec §11 CJ-24; road map "creator-jobs" CJ2a): hard
239	/// cuts from a deterministic picture difference, no ML.
240	///
241	/// **The signature** is spike CJ-S4's: a 4 × 4 × 4 colour histogram — the
242	/// top two bits of each of R, G and B — of the frame at long side 256, in
243	/// whole-pixel counts. **The distance** is their L1 summed exactly in
244	/// integers and divided once by the pixel count (0…2), so two distances
245	/// equal in counts are equal to the bit — a flash's two sides tie, as the
246	/// cut rule's tie-break needs.
247	///
248	/// **Stored per grid index** (`frames.bin`, one 16-byte little-endian record
249	/// per index from 0: `Int64` pts in ticks, −1 for no frame, `Float32` d1,
250	/// `Float32` d2): d1(i) is the distance to p1(i), the greatest index below i
251	/// holding a frame; d2(i) to p2(i), the greatest below p1(i); none → 0. Both
252	/// depend only on the frame and the two kept frames before it (CJ-22).
253	///
254	/// **The cut rule, applied when answered** (`cuts`): frame i is a cut when
255	/// d1(i) ≥ T; d2(n(i)) ≥ T, n(i) the least index above i holding a frame,
256	/// the test passing when no frame lies in i+1…i+m+1 or at the media's end;
257	/// and d1(i) is the largest d1 over i−m…i+m, an empty index counting 0, ties
258	/// to the earlier. T = 0.34, m = 12; the read margin is m + 1.
259	enum AnalysisShots {
260	    static let longSide = 256
261	    static let threshold: Float = 0.34
262	    static let neighbourhood = 12
263	    /// The read margin, m + 1 indices each side.
264	    static var margin: Int { neighbourhood + 1 }
265	    static let payloadName = "frames.bin"
266	    static let recordSize = 16
267	    /// A job publishes at each range's end and after this much wall time.
268	    static let publishInterval: TimeInterval = 30
269	
270	    /// What the stored values depend on (never T or m): the stamp's digest.
271	    static let parameters: [String: Any] = [
272	        "signature": "rgb_histogram", "bits_per_channel": 2, "long_side": longSide,
273	        "distance": "l1_counts",
274	    ]
275	
276	    struct Record: Equatable {
277	        var pts: Int64
278	        var d1: Float
279	        var d2: Float
280	
281	        static let empty = Record(pts: -1, d1: 0, d2: 0)
282	        var holdsFrame: Bool { pts >= 0 }
283	    }
284	
285	    // MARK: - The signature
286	
287	    /// 64 counts of a picture's colours by their top two bits.
288	    static func signature(_ picture: AnalysisPicture) -> [Int32] {
289	        var counts = [Int32](repeating: 0, count: 64)
290	        for y in 0..<picture.height {
291	            let row = picture.bytes + y * picture.bytesPerRow
292	            for x in 0..<picture.width {
293	                let p = row + x * 4
294	                let bin = Int(p[2] >> 6) << 4 | Int(p[1] >> 6) << 2 | Int(p[0] >> 6)
295	                counts[bin] += 1
296	            }
297	        }
298	        return counts
299	    }
300	
301	    /// L1 of two signatures over the first one's pixel count.
302	    static func distance(_ a: [Int32], _ b: [Int32]) -> Float {
303	        var sum: Int64 = 0
304	        var total: Int64 = 0
305	        for i in 0..<min(a.count, b.count) {
306	            sum += Int64(abs(a[i] - b[i]))
307	            total += Int64(a[i])
308	        }
309	        return total > 0 ? Float(Double(sum) / Double(total)) : 0
310	    }
311	
312	    // MARK: - frames.bin
313	
314	    /// Every record of a payload, `count` long; an index past the bytes is
315	    /// empty.
316	    static func decode(_ data: Data, count: Int) -> [Record] {
317	        var records = [Record](repeating: .empty, count: count)
318	        data.withUnsafeBytes { raw in
319	            let available = min(count, raw.count / recordSize)
320	            for k in 0..<available {
321	                let o = k * recordSize
322	                let pts = Int64(littleEndian: raw.loadUnaligned(fromByteOffset: o, as: Int64.self))
323	                let d1 = UInt32(littleEndian: raw.loadUnaligned(fromByteOffset: o + 8, as: UInt32.self))
324	                let d2 = UInt32(littleEndian: raw.loadUnaligned(fromByteOffset: o + 12, as: UInt32.self))
325	                records[k] = Record(pts: pts, d1: Float(bitPattern: d1), d2: Float(bitPattern: d2))
326	            }
327	        }
328	        return records
329	    }
330	
331	    /// One record's 16 bytes.
332	    static func bytes(of record: Record) -> [UInt8] {
333	        var out: [UInt8] = []
334	        out.reserveCapacity(recordSize)
335	        withUnsafeBytes(of: record.pts.littleEndian) { out += $0 }
336	        withUnsafeBytes(of: record.d1.bitPattern.littleEndian) { out += $0 }
337	        withUnsafeBytes(of: record.d2.bitPattern.littleEndian) { out += $0 }
338	        return out
339	    }
340	
341	    /// `data` made `count` records long (new ones empty), then every index of
342	    /// `covered` written: its record when `records` holds one, else empty.
343	    static func merge(
344	        _ data: inout Data, count: Int, records: [Int: Record], covered: [ClosedRange<Int>]
345	    ) {
346	        let length = count * recordSize
347	        if data.count < length {
348	            var tail = Data()
349	            for _ in 0..<((length - data.count) / recordSize) { tail.append(contentsOf: bytes(of: .empty)) }
350	            data.append(tail)
351	        } else if data.count > length {
352	            data.removeSubrange(length..<data.count)
353	        }
354	        for range in covered {
355	            for k in range where k >= 0 && k < count {
356	                let o = data.startIndex + k * recordSize
357	                data.replaceSubrange(o..<(o + recordSize), with: bytes(of: records[k] ?? .empty))
358	            }
359	        }
360	    }
361	
362	    // MARK: - The cut rule
363	
364	    /// The cuts among `window`'s indices of `records` (the whole grid).
365	    static func cuts(
366	        _ records: [Record], in window: ClosedRange<Int>, threshold: Float = threshold,
367	        m: Int = neighbourhood
368	    ) -> [Int] {
369	        let n = records.count
370	        func holds(_ i: Int) -> Bool { i >= 0 && i < n && records[i].holdsFrame }
371	        let low = max(0, window.lowerBound)
372	        let high = min(n - 1, window.upperBound)
373	        guard low <= high else { return [] }
374	        var found: [Int] = []
375	        for i in low...high where holds(i) && records[i].d1 >= threshold {
376	            let d = records[i].d1
377	            // A single flash returning to the shot: the next frame within
378	            // m + 1 must differ from the frame before this one too.
379	            var next: Int?
380	            if i + 1 <= min(n - 1, i + m + 1) {
381	                next = (i + 1...min(n - 1, i + m + 1)).first(where: holds)
382	            }
383	            if let next, records[next].d2 < threshold { continue }
384	            var largest = true
385	            for j in max(0, i - m)...min(n - 1, i + m) where j != i {
386	                let other = holds(j) ? records[j].d1 : 0
387	                if (j < i && other >= d) || (j > i && other > d) {
388	                    largest = false
389	                    break
390	                }
391	            }
392	            if largest { found.append(i) }
393	        }
394	        return found
395	    }
396	
397	    // MARK: - The job
398	
399	    /// Runs `request`'s ranges in order, publishing at each range's end and
400	    /// every `publishInterval`. False when `cancelled()` stopped it.
401	    /// `progress` hears done / total of the ranges' indices after each
402	    /// stored frame (the Analyzing sheet's bar, spec §11 CJ-28).
403	    static func run(
404	        _ request: AnalysisRequest, cancelled: () -> Bool,
405	        progress: (Double) -> Void = { _ in }
406	    ) throws -> Bool {
407	        let grid = AnalysisGrid(media: request.media)
408	        let source = AnalysisFrames.Source(
409	            media: request.media, url: request.url, input: request.input)
410	        let total = max(1, request.ranges.reduce(0) { $0 + $1.count })
411	        var before = 0
412	        for range in request.ranges {
413	            var records: [Int: Record] = [:]
414	            var p1: [Int32]?
415	            var p2: [Int32]?
416	            var coveredFrom = range.lowerBound
417	            var lastIndex = range.lowerBound - 1
418	            var lastPublish = Date()
419	            let finished = try AnalysisFrames.read(
420	                range: range, grid: grid, source: source, longSide: longSide,
421	                cancelled: cancelled
422	            ) { k, pts, picture in
423	                let signature = signature(picture)
424	                if k >= range.lowerBound {
425	                    records[k] = Record(
426	                        pts: pts, d1: p1.map { distance(signature, $0) } ?? 0,
427	                        d2: p2.map { distance(signature, $0) } ?? 0)
428	                    lastIndex = k
429	                    progress(Double(before + k - range.lowerBound + 1) / Double(total))
430	                }
431	                p2 = p1
432	                p1 = signature
433	                if Date().timeIntervalSince(lastPublish) >= publishInterval,
434	                    lastIndex >= coveredFrom
435	                {
436	                    try publish(request, grid: grid, covered: coveredFrom...lastIndex, records)
437	                    records.removeAll()
438	                    coveredFrom = lastIndex + 1
439	                    lastPublish = Date()
440	                }
441	            }
442	            guard finished else { return false }
443	            if coveredFrom <= range.upperBound {
444	                try publish(request, grid: grid, covered: coveredFrom...range.upperBound, records)
445	            }
446	            before += range.count
447	        }
448	        return true
449	    }
450	
451	    private static func publish(
452	        _ request: AnalysisRequest, grid: AnalysisGrid, covered: ClosedRange<Int>,
453	        _ records: [Int: Record]
454	    ) throws {
455	        try AnalysisStore.publish(
456	            kind: .shots, cacheDir: request.cacheDir, mediaID: request.media.id,
457	            stamp: request.stamp, covered: [covered], files: [payloadName]
458	        ) { data in
459	            merge(&data, count: grid.count, records: records, covered: [covered])
460	        }
461	    }
462	}
