467	/// The `faces` kind (spec §11 CJ-30…CJ-34; road map "creator-jobs" CJ3):
468	/// every face Vision finds in a media's picture, per sample of source time,
469	/// kept as one `samples.bin` per media (`AnalysisFaces+Samples.swift`).
470	/// Nothing visible; `get_media_analysis {kind: "faces"}` answers the samples.
471	///
472	/// **The grid** is the sample grid, `rate` a second (`AnalysisKind.grid(of:)`):
473	/// sample k at `ticks(k)` takes the first kept frame whose pts lies in
474	/// `[ticks(k), ticks(k) + one sample interval)`, else none (pts −1, no faces),
475	/// whatever the job's bounds; a frame serving two samples is analysed once
476	/// (CJ-33, `samples(at:after:grid:)`).
477	///
478	/// **The requests**, each FRESH on a fresh `VNImageRequestHandler` per frame:
479	/// `VNDetectFaceRectanglesRequest` revision 3 (box, confidence, roll, yaw),
480	/// then, with `landmarks`, `VNDetectFaceLandmarksRequest` revision 3 with
481	/// `.constellation76Points` over those faces (the mouth's inner-lip gap and
482	/// outer-lip width, each over the box's height in picture pixels). Each is
483	/// pinned to its device (CJ-32) and a job refuses to run when a request reads
484	/// back another (`FaceError.device`).
485	///
486	/// **The frames** are read through `AnalysisFrames.read`'s standard arms (the
487	/// direct reader, or the converted one for a converting media, CJ-S2 rule 5)
488	/// at `min(longSide, the media's long side)`. A job (`AnalysisSampleJob`)
489	/// publishes at each range's end and every `publishInterval`, mid-range only
490	/// through the samples decided.
491	enum AnalysisFaces {
492	    static let payloadName = "samples.bin"
493	
494	    /// CJ-30, CJ-S2 rule 2: samples a second.
495	    static let rate: Double = 10
496	    /// CJ-30, CJ-S2 rule 3: the read's long side (at most the media's own).
497	    static let longSide = 720
498	    /// CJ-30, CJ-S2 rule 4: the mouth measures stay in this kind.
499	    static let landmarks = true
500	    /// CJ-32, CJ-S2 rule 1, per request.
501	    static let rectanglesDevice: AnalysisVision.Device = .neuralEngine
502	    static let landmarksDevice: AnalysisVision.Device = .neuralEngine
503	    static let publishInterval: TimeInterval = 30
504	
505	    /// Each request's pinned readback, once.
506	    static let rectanglesReadback = AnalysisVision.pin(makeRectangles(), to: rectanglesDevice)
507	    static let landmarksReadback = AnalysisVision.pin(makeLandmarks([]), to: landmarksDevice)
508	    /// The stamp's `device`: `rectangles:<readback>;landmarks:<readback>`.
509	    static let device: String =
510	        "rectangles:\(rectanglesReadback)" + (landmarks ? ";landmarks:\(landmarksReadback)" : "")
511	
512	    /// The rate as the stamp spells it: "10", "5", "2.5".
513	    static var rateName: String {
514	        rate == rate.rounded() ? String(Int(rate)) : String(rate)
515	    }
516	
517	    static let vision = AnalysisVisionStamp(
518	        request: landmarks ? "face_rectangles+face_landmarks" : "face_rectangles",
519	        quality: landmarks ? "constellation_76" : "none", revision: 3, rate: rateName,
520	        readSize: String(longSide))
521	
522	    /// What the stored samples depend on: the stamp's digest.
523	    static let parameters: [String: Any] = [
524	        "request": vision.request, "quality": vision.quality, "revision": vision.revision,
525	        "rate": vision.rate, "read_size": vision.readSize, "landmarks": landmarks,
526	        "rectangles_device": rectanglesDevice.rawValue,
527	        "landmarks_device": landmarksDevice.rawValue,
528	        "file_version": Int(fileVersion), "record_bytes": Int(recordBytes),
529	        "sample": "first_frame_at_or_after_within_one_interval",
530	        "order": "box_centre_x_then_y", "mouth": "inner_gap_outer_width_over_box_height",
531	    ]
532	
533	    /// A fresh rectangles request, revision 3.
534	    static func makeRectangles() -> VNDetectFaceRectanglesRequest {
535	        let request = VNDetectFaceRectanglesRequest()
536	        request.revision = VNDetectFaceRectanglesRequestRevision3
537	        return request
538	    }
539	
540	    /// A fresh landmarks request over `faces`, revision 3, 76 points.
541	    static func makeLandmarks(_ faces: [VNFaceObservation]) -> VNDetectFaceLandmarksRequest {
542	        let request = VNDetectFaceLandmarksRequest()
543	        request.revision = VNDetectFaceLandmarksRequestRevision3
544	        request.constellation = .constellation76Points
545	        request.inputFaceObservations = faces
546	        return request
547	    }
548	
549	    enum FaceError: LocalizedError {
550	        case device(String)
551	
552	        var errorDescription: String? {
553	            switch self {
554	            case .device(let named):
555	                return "a face request ran on \(named), not \(AnalysisFaces.device)"
556	            }
557	        }
558	    }
559	
560	    /// Vision's lower-left box in CJ-22's frame: top-left, y down, 0…1.
561	    static func topLeft(_ box: CGRect) -> CGRect {
562	        CGRect(x: box.minX, y: 1 - box.maxY, width: box.width, height: box.height)
563	    }
564	
565	    /// CJ-31: by box centre x, then y (top-left frame), exact float compare.
566	    static func ordered(_ faces: [Face]) -> [Face] {
567	        faces.sorted { a, b in
568	            let ax = a.x + a.width / 2, bx = b.x + b.width / 2
569	            if ax != bx { return ax < bx }
570	            return a.y + a.height / 2 < b.y + b.height / 2
571	        }
572	    }
573	
574	    /// Every face in `picture`: the requests (above), ordered.
575	    static func faces(in picture: AnalysisPicture) throws -> [Face] {
576	        var wrapped: CVPixelBuffer?
577	        guard CVPixelBufferCreateWithBytes(
578	            kCFAllocatorDefault, picture.width, picture.height, REDACTED,
579	            UnsafeMutableRawPointer(mutating: picture.bytes), picture.bytesPerRow, nil, nil, nil,
580	            &wrapped) == kCVReturnSuccess, let wrapped
581	        else { throw AnalysisFrames.ReadError.reader("the frame could not be wrapped") }
582	        let rectangles = makeRectangles()
583	        let named = AnalysisVision.pin(rectangles, to: rectanglesDevice)
584	        guard named == rectanglesReadback else { throw FaceError.device("rectangles:\(named)") }
585	        try VNImageRequestHandler(cvPixelBuffer: wrapped, options: [:]).perform([rectangles])
586	        let observations = rectangles.results ?? []
587	        var faces = observations.map { o -> Face in
588	            let box = topLeft(o.boundingBox)
589	            return Face(
590	                x: Float(box.minX), y: Float(box.minY), width: Float(box.width),
591	                height: Float(box.height), confidence: o.confidence,
592	                roll: o.roll?.floatValue ?? .nan, yaw: o.yaw?.floatValue ?? .nan,
593	                mouthGap: .nan, mouthWidth: .nan)
594	        }
595	        guard landmarks, !observations.isEmpty else { return ordered(faces) }
596	        let marks = makeLandmarks(observations)
597	        let markNamed = AnalysisVision.pin(marks, to: landmarksDevice)
598	        guard markNamed == landmarksReadback else { throw FaceError.device("landmarks:\(markNamed)") }
599	        try VNImageRequestHandler(cvPixelBuffer: wrapped, options: [:]).perform([marks])
600	        let size = CGSize(width: picture.width, height: picture.height)
601	        for (i, o) in (marks.results ?? []).enumerated() where i < faces.count {
602	            let (gap, width) = mouth(o, size: size)
603	            faces[i].mouthGap = gap
604	            faces[i].mouthWidth = width
605	        }
606	        return ordered(faces)
607	    }
608	
609	    /// The inner lips' vertical extent and the outer lips' horizontal extent,
610	    /// each over the box's height in picture pixels (image axes, raw); NaN
611	    /// when Vision gave no lips.
612	    static func mouth(_ face: VNFaceObservation, size: CGSize) -> (Float, Float) {
613	        let boxHeight = Double(face.boundingBox.height) * Double(size.height)
614	        guard boxHeight > 0,
615	            let inner = face.landmarks?.innerLips?.pointsInImage(imageSize: size),
616	            let outer = face.landmarks?.outerLips?.pointsInImage(imageSize: size),
617	            let top = inner.map(\.y).max(), let bottom = inner.map(\.y).min(),
618	            let right = outer.map(\.x).max(), let left = outer.map(\.x).min()
619	        else { return (.nan, .nan) }
620	        return (Float((top - bottom) / boxHeight), Float((right - left) / boxHeight))
621	    }
622	
623	    /// The samples of the sample grid `grid` the frame at `pts` serves —
624	    /// those k with `previous < ticks(k) ≤ pts` and `pts < ticks(k) + one
625	    /// interval` (`previous` the kept frame before it, nil at the media's
626	    /// start); nil when none.
627	    static func samples(at pts: Int64, after previous: Int64?, grid: AnalysisGrid)
628	        -> ClosedRange<Int>?
629	    {
630	        let after = previous ?? Int64.min
631	        let upto = pts
632	        var high = min(grid.lastIndex, Int((Double(upto) * grid.rate).rounded(.down)) + 1)
633	        while high >= 0, grid.ticks(of: high) > upto { high -= 1 }
634	        var low = high + 1
635	        while low > 0 {
636	            let t = grid.ticks(of: low - 1)
637	            guard t > after, Double(pts) < Double(t) + grid.frameTicks else { break }
638	            low -= 1
639	        }
640	        return low <= high ? low...high : nil
641	    }
642	
643	    // MARK: - The job
644	
645	    /// Runs `request`'s ranges (sample indices) in order through
646	    /// `AnalysisSampleJob`. False when `cancelled()` stopped it; `progress`
647	    /// hears the share of samples decided.
648	    static func run(
649	        _ request: AnalysisRequest, cancelled: () -> Bool, progress: (Double) -> Void
650	    ) throws -> Bool {
651	        let grid = request.kind.grid(of: request.media)
652	        return try AnalysisSampleJob.run(
653	            request, grid: grid, longSide: longSide, publishInterval: publishInterval,
654	            cancelled: cancelled, progress: progress, analyse: { try faces(in: $0) }
655	        ) { covering, found in
656	            try AnalysisStore.publishFile(
657	                kind: .faces, cacheDir: request.cacheDir, mediaID: request.media.id,
658	                stamp: request.stamp, covered: [covering], files: [payloadName]
659	            ) { onDisk, partial in
660	                try write(
661	                    onDisk: onDisk, partial: partial, count: grid.count, covering: covering,
662	                    samples: found.mapValues { Sample(pts: $0.pts, faces: $0.value) })
663	            }
664	        }
665	    }
666	}
