968	/// with `hasVideo`, the clip's `enabled.video` on; any other clip named is
969	/// skipped. **Wants** are one `shots` request per media over the UNION of
970	/// its targets' played windows, never their hull: `analysisRequest` once per
971	/// window and the misses' ranges merged, so a gap no clip plays is never
972	/// read. **The plan** reads the store, maps each cut inside a target's window
973	/// to timeline time on the canvas grid, drops one within a canvas frame of
974	/// either edge, counts the ceiling with the linked partners `split` also
975	/// cuts BEFORE any op, and answers one `split` per cut, latest first, so the
976	/// original id keeps the head.
977	enum ShotSplit {
978	    static let actionName = "Split at Shot Changes"
979	
980	    struct Target {
981	        let clip: ClipSnapshot
982	        let media: MediaSnapshot
983	        let times: AnalysisClipTimes
