1025	    /// Whether `clip` is a target: a media clip whose media is a video with
1026	    /// pictures, its picture switched on.
1027	    static func qualifies(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
1028	        guard case .media(let id, _, _) = clip.source, clip.enabled.video,
1029	            let media = snapshot.media(id)
