1042	    /// ids skipped.
1043	    static func targets(_ ids: [UInt32], in project: ReelProject)
1044	        -> (targets: [Target], skipped: [UInt32])
1045	    {
1046	        let snapshot = project.snapshot
1047	        var targets: [Target] = []
1048	        var skipped: [UInt32] = []
1049	        for id in ids where !targets.contains(where: { $0.clip.id == id }) {
1050	            guard let clip = snapshot.clip(id), qualifies(clip, in: snapshot),
1051	                let media = snapshot.media(for: clip)
1052	            else {
1053	                if !skipped.contains(id) { skipped.append(id) }
1054	                continue
1055	            }
1056	            targets.append(Target(
1057	                clip: clip, media: media,
1058	                times: AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(id))))
