1156	    /// nest's. Only ever handed the UNSCOPED project's snapshot.
1157	    static func clipCount(_ snapshot: ProjectSnapshot) -> Int {
1158	        snapshot.clips.count + snapshot.nests.reduce(0) { $0 + $1.clips.count }
1159	    }
