import Foundation

// What a cutout asks of the analysis lane (road map creator-jobs CO2b, spec §11 CO-22): the windows
// a cut-out clip plays, the grid indices CO-24's lookup can ask of each, which open masks jobs a
// caller shares, and the requests it wants. Names no `rc_*` (CJ-8 (l)): the plan and the snapshot
// come through `ReelProject`. The document (`ProjectDocument+Masks.swift`), an export and a frame
// (`Exporter+Masks.swift`) are its three callers. A cut picture's one window, of the kind its
// subject asks, is windowed apart from the plan's segments (road map creator-jobs CO10b, spec §11
// CO-106).

/// One window of a cut-out clip, in FORWARD source ticks of its media, `[lower, upper)`, and the
/// analysis kind its masks are: `masks`, or a foreground picture's `foreground` (CO-106).
struct CutoutWindow: Equatable {
    let clip: UInt32
    let media: UInt32
    let lower: Ticks
    let upper: Ticks
    var kind: AnalysisKind = .masks
}

/// Who wanted a request (the dev log's `role`).
enum CutoutWantRole: String {
    case document, export, frame
}

/// A media whose request could not be made, named by the first window's clip of that media.
struct CutoutWantFailure: Equatable {
    let clip: UInt32
    let message: String
}

/// A request's state on the lane, from `AnalysisLane.run(of:)`: started and not ended, queued and
/// not started, or ended (or unknown).
enum CutoutRunState {
    case running, queued, ended
}

enum CutoutWants {
    /// The documents' wants, in order: every `ensureMasks()` builds and wants here.
    static let queue = DispatchQueue(label: "com.kgalligan.framejob.cutout-wants", qos: .utility)

    // MARK: - Windows (CO-22 (a))

    /// Every plan video segment (duration > 0) of a clip whose BASE `video.cutout` is set, clipped
    /// to `range` (nil: the whole segment), as a forward window — mirrored about the clip's pivot
    /// when it plays reversed. A segment `range` misses gives none.
    static func windows(
        plan: CompositionPlan, snapshot: ProjectSnapshot, range: Range<Ticks>?
    ) -> [CutoutWindow] {
        var cutOut = Set<UInt32>()
        for clip in snapshot.clips + snapshot.nests.flatMap(\.clips) where clip.video?.cutout != nil {
            cutOut.insert(clip.id)
        }
        guard !cutOut.isEmpty else { return [] }
        let pivots = CutoutPlan(plan: plan, snapshot: snapshot).pivots
        var out: [CutoutWindow] = []
        for track in plan.videoTracks {
            for segment in track.segments where segment.duration > 0 && cutOut.contains(segment.clip) {
                var a = segment.start
                var b = segment.start + segment.duration
                if let range {
                    a = max(a, range.lowerBound)
                    b = min(b, range.upperBound)
                }
                guard a < b else { continue }
                let window = window(segment, from: a, to: b, pivot: pivots[segment.clip])
                if !out.contains(window) { out.append(window) }
            }
        }
        return out
    }

    /// Every plan video segment (duration > 0) of `clip`, whatever its cutout, as a forward
    /// window — mirrored about the clip's pivot when it plays reversed. The camera's crop on the
    /// person reads these (road map creator-jobs CO7, spec §11 CO-70).
    static func windows(of clip: UInt32, plan: CompositionPlan, snapshot: ProjectSnapshot)
        -> [CutoutWindow]
    {
        let pivot = (snapshot.clips + snapshot.nests.flatMap(\.clips)).first { $0.id == clip }
            .flatMap { ReverseMirror.pivot(for: $0, in: snapshot) }
            return
        }
        let owner = Self.maskWants[key]?.owner ?? AnalysisLane.shared.newOwner()
        Self.maskWants[key] = MaskWants(owner: owner, wanting: true)
        let snapshot = project.snapshot
        let urls = mediaURLs()
        guard let cacheDir = cacheDirectory else { return }
        CutoutWants.queue.async { [weak self] in
            var windows: [CutoutWindow] = []
            for handle in handles {
                // A cut picture's one window beside the plan's segments (spec §11 CO-106).
                let image = CutoutWants.imageWindows(snapshot: handle.snapshot, range: nil)
                let planned = handle.plan.map {
                    CutoutWants.windows(plan: $0, snapshot: handle.snapshot, range: nil)
                } ?? []
                for window in planned + image where !windows.contains(window) {
                    windows.append(window)
                }
            }
            let (requests, failures) = CutoutWants.wants(
                windows: windows, snapshot: snapshot, urls: urls, cacheDir: cacheDir)
            for failure in failures {
                NSLog("ProjectDocument: clip %u's masks cannot be made: %@", failure.clip,
                    failure.message)
            }
            AnalysisLane.shared.want(
                requests, owner: owner,
                alive: { RecipeSource.shared.project(for: key) != nil },
                settled: { self?.masksDidSettle() })
            #if FRAMEJOB_DEV_TOOLS
            CutoutWants.log(.document, owner: owner, requests)
            #endif
        }
    }

    /// This document's lane owner; nil before its first want. Main only (road map creator-jobs
    /// CO3: the Background section's Status and `analyze_cutout` read its runs).
    var maskOwner: Int? { Self.maskWants[recipeKey]?.owner }

    /// The Background section's Analyze Now and `analyze_cutout` (spec §11 CO-30 (c)): the
    /// wants made again (`ensureMasks()`, the one want path), then — on `CutoutWants.queue`,
    /// after that want — a failed or cancelled run of this document's owner runs again
    /// (`AnalysisLane.retry`). Main thread.
    func analyzeMasksNow() {
        ensureMasks()
        guard let owner = maskOwner else { return }
        CutoutWants.queue.async { AnalysisLane.shared.retry(owner: owner) }
    }

    /// A masks job this document wants landed or failed: the package's date re-read (the job
    /// may have created `cache/analysis/`), then the wants made again — what is still missing.
    /// The redraw is `.analysisDidPublish`'s (CO-22 (d)). Main thread.
    func masksDidSettle() {
        packageContentsDidChangeOnDisk()
        ensureMasks()
    }
}
